from dataclasses import dataclass, field

import pytest


@dataclass
class BoundedQueue:
    """FIFO queue of integers holding at most `capacity` items. Puts never block."""

    capacity: int
    items: list[int] = field(default_factory=list)

    def try_put(self, value: int) -> bool:
        """Append value if there is room. Return True if accepted, False if the queue is full."""
        if len(self.items) < self.capacity:
            self.items.append(value)
            return True
        return False


def accepted(cap: int, xs: list[int]) -> int:
    """Count how many puts into a BoundedQueue(cap) are accepted before it first reports full.

    Offers each element of xs to try_put in order and stops at the first
    rejected put. Returns the number of accepted puts. Raises ValueError
    if cap is negative.
    """
    if cap < 0:
        raise ValueError("capacity must be non-negative")
    q = BoundedQueue(capacity=cap)
    count = 0
    for x in xs:
        if not q.try_put(x):
            break
        count += 1
    return count


def test_bounded_queue_try_put_respects_capacity() -> None:
    q = BoundedQueue(capacity=2)
    assert q.try_put(1) is True
    assert q.try_put(2) is True
    assert q.try_put(3) is False
    assert q.items == [1, 2]


def test_bounded_queue_zero_capacity_rejects_everything() -> None:
    q = BoundedQueue(capacity=0)
    assert q.try_put(7) is False
    assert q.items == []


def test_accepted_stops_at_capacity() -> None:
    assert accepted(3, [1, 2, 3, 4, 5]) == 3


def test_accepted_capacity_larger_than_input() -> None:
    assert accepted(10, [1, 2, 3]) == 3


def test_accepted_zero_capacity() -> None:
    assert accepted(0, [1, 2, 3]) == 0


def test_accepted_empty_input() -> None:
    assert accepted(5, []) == 0


def test_accepted_exact_fit() -> None:
    assert accepted(2, [9, 8]) == 2


def test_accepted_negative_capacity_raises() -> None:
    with pytest.raises(ValueError):
        accepted(-1, [1, 2])
